// 转换和验证输入数据节点
// 输入格式示例：
// {
//   "mealTime": "2024-01-15T08:00:00",
//   "foods": [
//     {"name": "米饭", "quantity": "1碗"},
//     {"name": "青菜", "quantity": "200g"},
//     {"name": "鸡蛋", "quantity": "1个"}
//   ],
//   "userInfo": {
//     "email": "user@example.com",  // 可选
//     "isDiabetic": true,  // 是否糖尿病患者
//     "diabetesType": "2型",  // 1型/2型/妊娠期/无
//     "currentMedication": "口服药",  // 胰岛素/口服药/无
//     "age": 45,
//     "gender": "男",
//     "height": 170,
//     "weight": 70
//   }
// }

const input = $input.item.json;

// 解析请求体
let requestData = input.body;
if (typeof requestData === 'string') {
  try {
    requestData = JSON.parse(requestData);
  } catch (e) {
    requestData = input.body || input;
  }
}

if (!requestData || typeof requestData !== 'object') {
  requestData = input;
}

// 生成唯一的提交ID
const submissionId = 'diabetes_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);

// 验证必填字段
const errors = [];

if (!requestData.mealTime) {
  errors.push('用餐时间(mealTime)是必填项');
}

if (!requestData.foods || !Array.isArray(requestData.foods) || requestData.foods.length === 0) {
  errors.push('食物列表(foods)是必填项，且不能为空');
}

// 验证食物数据格式
if (requestData.foods) {
  requestData.foods.forEach((food, index) => {
    if (!food.name) {
      errors.push(`食物列表第${index + 1}项缺少名称(name)`);
    }
    if (!food.quantity) {
      errors.push(`食物列表第${index + 1}项缺少数量(quantity)`);
    }
  });
}

// 如果有错误，返回错误信息
if (errors.length > 0) {
  return {
    json: {
      valid: false,
      errors: errors,
      submissionId: submissionId
    }
  };
}

// 转换数据格式
const convertedData = {
  submissionId: submissionId,
  mealTime: requestData.mealTime,
  foods: requestData.foods,
  userInfo: {
    email: (requestData.userInfo?.email || '').trim(),
    isDiabetic: requestData.userInfo?.isDiabetic || false,
    diabetesType: requestData.userInfo?.diabetesType || '无',
    currentMedication: requestData.userInfo?.currentMedication || '无',
    age: parseInt(requestData.userInfo?.age) || null,
    gender: requestData.userInfo?.gender || '',
    height: parseFloat(requestData.userInfo?.height) || null,
    weight: parseFloat(requestData.userInfo?.weight) || null,
    createdAt: new Date().toISOString()
  }
};

// 计算BMI（如果有身高体重）
if (convertedData.userInfo.height && convertedData.userInfo.weight) {
  const heightInMeters = convertedData.userInfo.height / 100;
  convertedData.userInfo.bmi = parseFloat((convertedData.userInfo.weight / (heightInMeters * heightInMeters)).toFixed(1));
}

return {
  json: {
    valid: true,
    data: convertedData
  }
};

// 解析食物重量节点（简化版）
// 只负责解析重量，不进行营养成分计算
// 营养成分分析交给DeepSeek AI处理

const data = $('转换和验证输入数据').first().json.data;

// 简单的数量单位估算（用于解析"1碗"、"2个"等）
const UNIT_WEIGHT_ESTIMATES = {
  "碗": 150,    // 默认1碗=150g（米饭、面条等）
  "个": 100,    // 默认1个=100g（馒头、包子、苹果等）
  "根": 200,    // 默认1根=200g（香蕉、玉米等）
  "片": 50,     // 默认1片=50g（面包等）
  "颗": 10,     // 默认1颗=10g（葡萄、草莓等）
  "块": 100,    // 默认1块=100g
  "把": 200,    // 默认1把=200g（青菜等）
  "只": 50,     // 默认1只=50g（鸡蛋、虾等）
  "杯": 250     // 默认1杯=250g（牛奶、豆浆等）
};

function parseWeight(quantity) {
  // 尝试解析为克数（如"200g"、"150克"）
  const gMatch = quantity.match(/(\d+(?:\.\d+)?)\s*(?:g|克|gram)/i);
  if (gMatch) {
    return parseFloat(gMatch[1]);
  }

  // 尝试解析为数量单位（如"1碗"、"2个"）
  const unitMatch = quantity.match(/(\d+(?:\.\d+)?)([个碗根片颗块把只杯])/);
  if (unitMatch) {
    const count = parseFloat(unitMatch[1]);
    const unit = unitMatch[2];
    if (UNIT_WEIGHT_ESTIMATES[unit]) {
      return UNIT_WEIGHT_ESTIMATES[unit] * count;
    }
  }

  // 如果都解析不了，返回null，让AI来处理
  return null;
}

// 解析所有食物的重量
const parsedFoods = data.foods.map((food) => {
  let weight = parseWeight(food.quantity);

  // 如果无法解析重量，使用默认值100g，让AI来估算
  if (!weight) {
    weight = 100; // 默认100g
  }

  return {
    name: food.name,
    quantity: food.quantity,
    weight: weight,
    weightEstimated: !parseWeight(food.quantity) // 标记重量是否为估算值
  };
});

return {
  json: {
    submissionId: data.submissionId,
    mealTime: data.mealTime,
    userInfo: data.userInfo,
    foods: parsedFoods
  }
};

// AI分析食物营养成分节点
// 调用DeepSeek AI来分析食物的营养成分（碳水、GI、GL值）

const data = $('解析食物重量').first().json;

// 构建食物列表字符串
const foodsList = data.foods.map((food, index) => {
  return `${index + 1}. ${food.name} - ${food.quantity}（约${food.weight}g${food.weightEstimated ? '，重量为估算值' : ''}）`;
}).join('\n');

// 构建AI提示词
const nutritionPrompt = `你是一位专业的营养师，擅长分析食物的营养成分，特别是对血糖有影响的指标。

请分析以下食物的营养成分，重点关注：
1. **碳水化合物含量**（g/100g，然后根据实际重量计算总碳水）
2. **GI值**（血糖指数，0-100）
3. **GL值**（血糖负荷，= 碳水 × GI / 100）

## 食物列表
${foodsList}

## 要求
1. 对于每个食物，根据其名称和重量，分析其营养成分
2. 如果食物名称是复合菜名（如"宫保鸡丁"），请分析其主要成分和整体营养成分
3. 如果重量是估算值，请基于常见分量进行合理估算
4. 使用中国食物成分表的标准数据
5. 对于不确定的食物，请基于食物类别进行合理估算

## 输出格式（必须严格遵循JSON格式）
请以JSON格式输出，格式如下：
\`\`\`json
{
  "foods": [
    {
      "name": "食物名称",
      "weight": 重量（克）,
      "carbs": 碳水化合物（克）,
      "gi": GI值（0-100）,
      "gl": GL值,
      "category": "食物类别（主食/蔬菜/水果/肉类/豆制品/奶制品/坚果/其他）",
      "note": "备注（如有估算值或特殊说明）"
    }
  ],
  "summary": {
    "totalCarbs": 总碳水化合物（克）,
    "totalGL": 总血糖负荷,
    "averageGI": 平均GI值（加权平均）,
    "estimatedFoods": ["使用了估算值的食物名称列表"]
  }
}
\`\`\`

## 重要提示
- 必须输出有效的JSON格式
- 所有数值必须是数字类型
- 如果某个食物不确定，请在note中说明
- 确保计算准确，特别是GL值（GL = 碳水 × GI / 100）

请开始分析：`;

return {
  json: {
    ...data,
    nutritionPrompt: nutritionPrompt
  }
};

