// 解析AI营养成分分析结果节点
// 从DeepSeek的响应中提取营养成分数据

const aiResponse = $input.item.json;
const originalData = $('解析食物重量').first().json;

// 提取AI生成的文本
let responseText = '';
if (aiResponse.choices && aiResponse.choices[0] && aiResponse.choices[0].message) {
  responseText = aiResponse.choices[0].message.content;
} else if (aiResponse.content) {
  responseText = aiResponse.content;
} else if (typeof aiResponse === 'string') {
  responseText = aiResponse;
}

// 尝试从响应中提取JSON
let nutritionData = null;

// 方法1：尝试直接解析JSON（如果响应就是JSON）
try {
  nutritionData = JSON.parse(responseText);
} catch (e) {
  // 方法2：尝试从代码块中提取JSON
  const jsonMatch = responseText.match(/```json\s*([\s\S]*?)\s*```/);
  if (jsonMatch) {
    try {
      nutritionData = JSON.parse(jsonMatch[1]);
    } catch (e2) {
      // 方法3：尝试提取JSON对象（不使用代码块标记）
      const jsonObjectMatch = responseText.match(/\{[\s\S]*"foods"[\s\S]*\}/);
      if (jsonObjectMatch) {
        try {
          nutritionData = JSON.parse(jsonObjectMatch[0]);
        } catch (e3) {
          console.error('无法解析JSON:', e3);
        }
      }
    }
  }
}

// 如果无法解析，使用默认值并标记错误
if (!nutritionData || !nutritionData.foods) {
  console.warn('AI响应无法解析，使用默认值');

  // 使用默认值：假设所有食物都是中等碳水
  nutritionData = {
    foods: originalData.foods.map(food => ({
      name: food.name,
      weight: food.weight,
      carbs: (food.weight / 100) * 15, // 默认15g碳水/100g
      gi: 55, // 默认中等GI
      gl: (food.weight / 100) * 15 * 0.55,
      category: "其他",
      note: "AI分析失败，使用默认估算值"
    })),
    summary: {
      totalCarbs: originalData.foods.reduce((sum, food) => sum + (food.weight / 100) * 15, 0),
      totalGL: originalData.foods.reduce((sum, food) => sum + (food.weight / 100) * 15 * 0.55, 0),
      averageGI: 55,
      estimatedFoods: originalData.foods.map(f => f.name)
    }
  };
}

// 合并原始数据和AI分析结果
const foodsWithNutrition = originalData.foods.map((originalFood, index) => {
  const aiFood = nutritionData.foods[index] || nutritionData.foods.find(f => f.name === originalFood.name);

  if (aiFood) {
    return {
      name: originalFood.name,
      quantity: originalFood.quantity,
      weight: aiFood.weight || originalFood.weight,
      carbs: parseFloat((aiFood.carbs || 0).toFixed(2)),
      gi: parseInt(aiFood.gi || 55),
      gl: parseFloat((aiFood.gl || 0).toFixed(2)),
      category: aiFood.category || "其他",
      note: aiFood.note || "",
      aiAnalyzed: true
    };
  } else {
    // 如果AI没有分析这个食物，使用默认值
    return {
      name: originalFood.name,
      quantity: originalFood.quantity,
      weight: originalFood.weight,
      carbs: parseFloat(((originalFood.weight / 100) * 15).toFixed(2)),
      gi: 55,
      gl: parseFloat(((originalFood.weight / 100) * 15 * 0.55).toFixed(2)),
      category: "其他",
      note: "AI未分析此食物，使用默认估算值",
      aiAnalyzed: false
    };
  }
});

// 计算汇总数据（使用AI提供的数据，如果没有则重新计算）
const summary = nutritionData.summary || {
  totalCarbs: parseFloat(foodsWithNutrition.reduce((sum, f) => sum + f.carbs, 0).toFixed(2)),
  totalGL: parseFloat(foodsWithNutrition.reduce((sum, f) => sum + f.gl, 0).toFixed(2)),
  averageGI: (() => {
    let weightedGI = 0;
    let totalCarbs = 0;
    foodsWithNutrition.forEach(f => {
      if (f.carbs > 0) {
        weightedGI += f.gi * f.carbs;
        totalCarbs += f.carbs;
      }
    });
    return totalCarbs > 0 ? Math.round(weightedGI / totalCarbs) : 0;
  })(),
  estimatedFoods: nutritionData.summary?.estimatedFoods || foodsWithNutrition.filter(f => f.note || !f.aiAnalyzed).map(f => f.name)
};

return {
  json: {
    submissionId: originalData.submissionId,
    mealTime: originalData.mealTime,
    userInfo: originalData.userInfo,
    foods: foodsWithNutrition,
    summary: summary,
    aiResponseRaw: responseText // 保留原始响应用于调试
  }
};

// 血糖预测节点
// 基于碳水化合物计数法和GI值进行血糖预测

const data = $('解析AI营养成分结果').first().json;
const { summary, userInfo } = data;

// 血糖预测算法
// 1. 空腹血糖预测（基于基础代谢和当前状态）
// 2. 餐后2小时血糖预测（基于碳水化合物和GI值）

function predictBloodGlucose(totalCarbs, averageGI, userInfo) {
  const results = {
    fastingGlucose: null,
    postprandial2hGlucose: null,
    predictions: {}
  };

  // 基础血糖水平（假设正常范围）
  let baseFastingGlucose = 5.5; // mmol/L（正常空腹血糖）
  let basePostprandialGlucose = 7.0; // mmol/L（正常餐后2小时）

  // 根据用户信息调整基础值
  if (userInfo.isDiabetic) {
    if (userInfo.diabetesType === '1型') {
      baseFastingGlucose = 7.0; // 1型糖尿病患者通常需要胰岛素
      basePostprandialGlucose = 9.0;
    } else if (userInfo.diabetesType === '2型') {
      baseFastingGlucose = 6.5;
      basePostprandialGlucose = 8.5;
    } else if (userInfo.diabetesType === '妊娠期') {
      baseFastingGlucose = 5.3;
      basePostprandialGlucose = 6.7;
    }
  }

  // 空腹血糖预测（相对稳定，主要受基础代谢影响）
  // 如果有BMI信息，可以稍微调整
  if (userInfo.bmi) {
    if (userInfo.bmi > 28) {
      baseFastingGlucose += 0.5; // 肥胖可能增加空腹血糖
    } else if (userInfo.bmi < 18.5) {
      baseFastingGlucose -= 0.3;
    }
  }

  results.fastingGlucose = parseFloat(baseFastingGlucose.toFixed(1));

  // 餐后2小时血糖预测
  // 基于碳水化合物计数法：每10g碳水化合物约升高血糖1-2mmol/L
  // GI值影响血糖上升速度和峰值
  const carbsImpact = (totalCarbs / 10) * 1.5; // 基础影响

  // GI值调整系数（高GI食物血糖上升更快更高）
  let giMultiplier = 1.0;
  if (averageGI >= 70) {
    giMultiplier = 1.3; // 高GI食物
  } else if (averageGI >= 55) {
    giMultiplier = 1.1; // 中GI食物
  } else {
    giMultiplier = 0.9; // 低GI食物
  }

  // 计算餐后血糖上升
  const glucoseRise = carbsImpact * giMultiplier;

  // 考虑药物影响
  let medicationAdjustment = 0;
  if (userInfo.currentMedication === '胰岛素') {
    medicationAdjustment = -2.0; // 胰岛素会降低血糖
  } else if (userInfo.currentMedication === '口服药') {
    medicationAdjustment = -1.5; // 口服药也会降低血糖
  }

  // 最终餐后2小时血糖
  const predictedPostprandial = basePostprandialGlucose + glucoseRise + medicationAdjustment;

  // 确保预测值在合理范围内（2-20 mmol/L）
  results.postprandial2hGlucose = Math.max(2.0, Math.min(20.0, parseFloat(predictedPostprandial.toFixed(1))));

  // 血糖评估
  let fastingStatus = '正常';
  if (results.fastingGlucose < 3.9) {
    fastingStatus = '偏低（可能低血糖）';
  } else if (results.fastingGlucose >= 7.0) {
    fastingStatus = '偏高（可能糖尿病）';
  } else if (results.fastingGlucose >= 6.1) {
    fastingStatus = '偏高（空腹血糖受损）';
  }

  let postprandialStatus = '正常';
  if (userInfo.isDiabetic) {
    if (results.postprandial2hGlucose < 4.0) {
      postprandialStatus = '偏低（可能低血糖）';
    } else if (results.postprandial2hGlucose > 10.0) {
      postprandialStatus = '偏高（需要关注）';
    } else if (results.postprandial2hGlucose > 7.8) {
      postprandialStatus = '偏高（餐后血糖受损）';
    }
  } else {
    if (results.postprandial2hGlucose < 4.0) {
      postprandialStatus = '偏低（可能低血糖）';
    } else if (results.postprandial2hGlucose > 7.8) {
      postprandialStatus = '偏高（需要关注）';
    }
  }

  results.predictions = {
    fastingStatus: fastingStatus,
    postprandialStatus: postprandialStatus,
    riskLevel: '低',
    recommendations: []
  };

  // 风险评估
  if (results.postprandial2hGlucose > 10.0 || results.fastingGlucose > 7.0) {
    results.predictions.riskLevel = '高';
    results.predictions.recommendations.push('建议立即监测血糖，必要时咨询医生');
  } else if (results.postprandial2hGlucose > 7.8 || results.fastingGlucose > 6.1) {
    results.predictions.riskLevel = '中';
    results.predictions.recommendations.push('建议调整饮食，选择低GI食物');
  }

  // 添加运动建议
  if (results.postprandial2hGlucose > 7.8) {
    results.predictions.recommendations.push('建议餐后30-60分钟进行轻度运动（如散步）');
  }

  return results;
}

// 执行预测
const glucosePrediction = predictBloodGlucose(
  summary.totalCarbs,
  summary.averageGI,
  userInfo
);

return {
  json: {
    ...data,
    glucosePrediction: glucosePrediction
  }
};

// AI分析提示词格式化节点
// 为DeepSeek生成完整的分析提示词

const data = $('血糖预测').first().json;

const userPrompt = `作为专业的糖尿病专家医生，请为患者进行详细的饮食分析。以下是患者的信息和食物数据：

## 用户信息
- **是否糖尿病患者**：${data.userInfo.isDiabetic ? '是' : '否'}
- **糖尿病类型**：${data.userInfo.diabetesType}
- **当前用药**：${data.userInfo.currentMedication}
- **年龄**：${data.userInfo.age || '未提供'}岁
- **性别**：${data.userInfo.gender || '未提供'}
- **身高**：${data.userInfo.height || '未提供'}cm
- **体重**：${data.userInfo.weight || '未提供'}kg
- **BMI**：${data.userInfo.bmi || '未计算'}

## 用餐信息
- **用餐时间**：${new Date(data.mealTime).toLocaleString('zh-CN')}
- **食物组合**：
${data.foods.map((food, index) => {
  return `${index + 1}. ${food.name} - ${food.quantity}（约${food.weight}g）
     - 碳水化合物：${food.carbs}g
     - GI值：${food.gi}
     - GL值：${food.gl}
     - 类别：${food.category || '未分类'}
     ${food.note ? `⚠️ ${food.note}` : ''}`;
}).join('\n')}

## 营养分析
- **总碳水化合物**：${data.summary.totalCarbs}g
- **总血糖负荷(GL)**：${data.summary.totalGL}
- **平均GI值**：${data.summary.averageGI}
${data.summary.estimatedFoods && data.summary.estimatedFoods.length > 0 ? `- **使用估算值的食物**：${data.summary.estimatedFoods.join('、')}（AI分析时使用了估算值）` : ''}

## 血糖预测
- **预测空腹血糖**：${data.glucosePrediction.fastingGlucose} mmol/L（${data.glucosePrediction.predictions.fastingStatus}）
- **预测餐后2小时血糖**：${data.glucosePrediction.postprandial2hGlucose} mmol/L（${data.glucosePrediction.predictions.postprandialStatus}）
- **风险等级**：${data.glucosePrediction.predictions.riskLevel}

## 报告要求

请生成一份详细的健康分析报告，包含以下4个核心部分：

### 1. 糖尿病的含义（基础科普）
- 什么是糖尿病（简单易懂的解释）
- 糖尿病的类型（1型、2型、妊娠期）
- 血糖的正常范围
- 糖尿病的主要症状和危害
- 预防糖尿病的重要性（针对非糖尿病患者）

### 2. 食物组合的详细分析
- **总体评价**：这餐食物的血糖影响评估
- **每样食物分析**：
  ${data.foods.map(food => {
    const note = food.note ? `（${food.note}）` : '';
